#!/usr/bin/env python3
"""Situationen: von 16 auf 48 Fragen (je 12 in Umgang und Stall, Reitbahn, Gelände, Straßenverkehr) und Zähler "Frage n / N" (idempotent).
Alle neuen Fragen sind Entwürfe (Hinweis "mit Lehrbuch prüfen" steht in der Karte). Aufruf im Repo-Ordner: python3 -I src/situationen_patch.py"""
import re
s=open('index.html',encoding='utf8').read()
NEW=[
# Umgang und Stall
('Umgang und Stall','Du willst ein Pferd aus der Box holen. Wie gehst du hinein?','Ich spreche es an, gehe von vorn seitlich hinein und lege die Hand auf die Schulter',['Ich öffne die Tür und gehe leise von hinten hinein','Ich gehe schnell hinein, damit es keine Zeit zum Erschrecken hat'],'Das Pferd soll dich sehen und hören, bevor du es berührst. Wer von hinten kommt, kann es erschrecken und einen Tritt riskieren.'),
('Umgang und Stall','Du gibst dem Pferd ein Leckerli. Wie?','Auf der flachen Hand, mit gestreckten Fingern',['Zwischen den Fingerspitzen','Hoch über dem Kopf, damit es sich streckt'],'Auf der flachen Hand schnappt das Pferd nicht nach den Fingern. Zu viele Leckerlis machen Pferde aufdringlich, gib nur nach Absprache.'),
('Umgang und Stall','Das Pferd am Zaun schaut dich bettelnd an. Darfst du Futter geben?','Nur nach Absprache mit dem Reitlehrer oder dem Futterplan',['Ja, ein bisschen Brot schadet nicht','Ja, frisches Gras vom Wegrand ist immer gut'],'Jedes Pferd hat einen Futterplan. Zu viel oder das falsche Futter kann zu Koliken oder Hufrehe führen.'),
('Umgang und Stall','Du führst ein Pferd durch eine enge Tür. Wie?','Ich gehe zuerst durch und führe es gerade und ruhig nach',['Ich lasse es allein vorangehen','Ich dränge es seitlich an der Wand vorbei'],'Enge Stellen machen Pferden Angst. Gerade und in Ruhe durch, damit es sich nicht an Rahmen oder Wand verletzt.'),
('Umgang und Stall','Du verlässt die Box. Was ist wichtig?','Tür sorgfältig schließen und verriegeln',['Die Tür nur anlehnen, ich bin gleich zurück','Offen lassen, damit das Pferd frische Luft hat'],'Ein Pferd, das unbemerkt aus der Box kommt, ist sich selbst und anderen gefährlich.'),
('Umgang und Stall','Dein Pferd lahmt beim Führen auf dem Hof. Was tust du?','Ich reite es nicht und sage dem Reitlehrer oder Stallchef Bescheid',['Ich reite es trotzdem, es läuft sich warm','Ich lasse es einfach frei laufen'],'Lahmheit ist ein Warnzeichen. Ein verletztes Pferd darf nicht geritten werden, die Ursache muss jemand mit Erfahrung prüfen.'),
('Umgang und Stall','Wo bindest du ein Pferd an?','An einem festen Ring, in Augenhöhe des Pferdes, mit Schlaufe oder Panikhaken',['An der Boxentür','An einem Zaunbrett'],'Ring und Schlaufe halten stand und lassen sich im Notfall lösen. Türen und Zaunbretter brechen, das Pferd erschrickt und kann sich verletzen.'),
# Reitbahn
('Reitbahn','Du kommst zur Reitbahn und willst hinein. Wie kündigst du dich an?','Ich rufe „Tür frei?“ und warte auf die Antwort',['Ich öffne und reite gleich ein','Ich klopfe einmal und gehe hinein'],'So wissen alle in der Bahn Bescheid, und nichts erschreckt die Pferde. Erst bei „Ja, bitte“ gehst du hinein.'),
('Reitbahn','Wie viel Abstand hältst du zum Pferd vor dir?','Mindestens eine Pferdelänge',['So nah wie möglich, ich bleibe dicht dran','Etwa eine Handbreit'],'Tritt ein Pferd aus, darf es kein anderes treffen. Eine Pferdelänge gibt Zeit zum Reagieren.'),
('Reitbahn','Das Pferd vor dir wird langsamer. Was tust du?','Ich halte Abstand und pariere rechtzeitig durch oder reite einen Zirkel',['Ich reite dicht auf, damit es schneller wird','Ich treibe mein Pferd und überhole eng'],'Du bist für den Abstand zuständig, nicht der Vordermann. Dicht auffahren ist gefährlich und stresst beide Pferde.'),
('Reitbahn','Dein Pferd geht mit dir durch. Was tust du?','Ruhig bleiben, einen kleinen Zirkel reiten und durchparieren',['Die Zügel loslassen','Mit den Fersen kräftig antreiben'],'Ein kleiner Zirkel bremst das Pferd. Loslassen oder Antreiben macht es schneller und noch aufgeregter.'),
('Reitbahn','In der Halle wird gerade longiert. Was beachtest du?','Ich halte großen Abstand, kreuze den Zirkel nicht und sage Bescheid, wo ich reite',['Ich reite mitten durch den Zirkel, das geht schnell','Ich überhole das longierte Pferd eng'],'Ein Pferd an der Longe kann nicht ausweichen. Wer den Zirkel kreuzt, kann sich in der Leine verfangen oder es erschrecken.'),
('Reitbahn','Du willst in der Halle aufsteigen. Wo?','In der Bahnmitte, mit Aufstiegshilfe oder mit Hilfe',['Direkt am Hufschlag, wo ich festen Halt habe','In der Ecke, da stört es niemanden'],'Auf dem Hufschlag stehst du im Weg. In der Mitte können alle ungehindert vorbeireiten.'),
('Reitbahn','Laut knallt eine Tür, dein Pferd erschrickt und springt zur Seite. Was tust du?','Ruhig sitzen bleiben, Zügel aufnehmen und durchparieren',['Mich festklammern und die Zügel hochziehen','Absteigen, solange es noch geht'],'Wer ruhig bleibt, beruhigt das Pferd. Festklammern oder Reißen an den Zügeln macht es nur unruhiger.'),
('Reitbahn','Du willst die Bahn verlassen. Wie?','Ich rufe „Tür frei?“, pariere durch und gehe im Schritt hinaus',['Ich reite im Trab hinaus','Ich reite durch die Mitte und lasse die Tür offen'],'Ein Pferd, das durch die Tür tritt, ist leicht erschreckt. Im Schritt und mit Absprache bleibt alles ruhig.'),
# Gelände
('Gelände','Der Ausritt beginnt. In welcher Gangart startest du?','Im Schritt, damit sich die Pferde aufwärmen',['Gleich im Galopp','Im Trab, damit alle wach werden'],'Die Muskeln brauchen Zeit zum Aufwärmen. Im Schritt gewöhnen sich die Pferde auch an die Umgebung.'),
('Gelände','Der Weg geht steil bergauf. Wie sitzt du?','Mit leicht nach vorn geneigtem Oberkörper, Hand an der Mähne',['Weit zurückgelehnt','Steif im Sattel sitzen bleiben'],'So entlastest du den Rücken des Pferdes, und es kann mit den Hinterbeinen schieben. Die Mähne gibt dir Halt, ohne am Zügel zu ziehen.'),
('Gelände','Der Weg führt steil bergab. Wie reitest du?','Im Schritt, gerade und aufrecht',['Im Trab, damit es schneller vorbei ist','Im Galopp mit langen Zügeln'],'Bergab trägt das Pferd viel Gewicht auf den Vorderbeinen. Im Schritt behält es das Gleichgewicht.'),
('Gelände','Dein Pferd bleibt vor einem Bach stehen. Was tust du?','Ruhig bleiben, Zeit geben und ein anderes Pferd vorangehen lassen',['Mit der Gerte schlagen','Umdrehen und davonreiten'],'Pferde misstrauen Wasser. Geduld und ein Vorreiter geben Vertrauen, Zwang erzeugt Angst.'),
('Gelände','Ein Pferd in der Gruppe hat eine rote Schleife am Schweif. Warum?','Es schlägt aus, die anderen sollen Abstand halten',['Es ist das Leitpferd','Es ist neu im Stall'],'Die rote Schleife ist ein bekanntes Warnzeichen. Dahinter reitet man mit großem Abstand.'),
('Gelände','Du reitest durch ein Weidetor, das geschlossen war. Was tust du danach?','Ich schließe es wieder',['Ich lasse es offen, die Nächsten kommen ja gleich','Ich hänge nur den Haken ein'],'Offene Tore lassen Tiere entkommen. Jedes Tor, das du öffnest, schließt du wieder.'),
('Gelände','Ein Gewitter zieht auf. Was tust du?','Ich breche den Ausritt ab und reite im Schritt auf sicherem Weg zurück',['Ich warte unter dem höchsten Baum','Ich galoppiere so schnell wie möglich heim'],'Einzelne hohe Bäume sind bei Blitzen gefährlich. Auf dem Heimweg bleibst du im Schritt, damit niemand stürzt.'),
('Gelände','Es geht heimwärts zum Stall. Wie reitest du das letzte Stück?','Im Schritt, damit die Pferde ruhig und trocken ankommen',['Im Galopp, die Pferde wollen ja heim','Im Trab bis in den Hof'],'Pferde sollen sich zum Schluss abkühlen. Wer heimwärts rennt, übt ein Pferd, das immer drängelt.'),
# Straßenverkehr
('Straßenverkehr','Ihr müsst eine Straße überqueren. Wie?','Alle gemeinsam, im Schritt, nach beiden Seiten schauend',['Einzeln im Trab, so schnell es geht','Im Galopp, damit kein Auto kommt'],'Eine geschlossene Gruppe im Schritt ist gut zu sehen und bleibt kontrollierbar. Wer rennt, riskiert einen Sturz oder einen Unfall.'),
('Straßenverkehr','Ein Lkw kommt euch entgegen, dein Pferd wird nervös. Was tust du?','Ich bleibe am rechten Rand, halte im Schritt an und spreche ruhig',['Ich wende und reite davon','Ich treibe vorwärts, damit es nicht stehen bleibt'],'Ruhe vom Reiter beruhigt das Pferd. Anhalten gibt dem Fahrer Zeit, langsam vorbeizufahren.'),
('Straßenverkehr','Du willst nach links abbiegen. Wie zeigst du das?','Mit dem ausgestreckten linken Arm, rechtzeitig vorher',['Gar nicht, die Fahrer sehen es schon','Mit der Gerte nach oben'],'Reiter zeigen die Richtung mit dem Arm. Je früher, desto besser können Autofahrer reagieren.'),
('Straßenverkehr','Die Straße ist nass oder glatt. Wie reitest du?','Im Schritt, vorsichtig und aufmerksam',['Im Trab, damit das Pferd Halt findet','Im Galopp, um schnell durchzukommen'],'Auf Asphalt rutschen Hufe, besonders bei Nässe. Im Schritt kann sich das Pferd sicher bewegen.'),
('Straßenverkehr','Du reitest an einem Fußgänger vorbei. Was tust du?','Ich halte Abstand, bleibe im Schritt und grüße freundlich',['Ich trabe an, damit es schnell geht','Ich reite eng vorbei, er soll ausweichen'],'Mit Rücksicht erschreckst du weder Menschen noch Pferd. Das schafft ein gutes Bild der Reiter.'),
('Straßenverkehr','Ein Traktor mit Anhänger nähert sich laut. Was tust du?','Ich halte rechts an, spreche ruhig und bitte den Fahrer, langsam zu fahren',['Ich reite im Galopp an ihm vorbei','Ich drehe um und reite im Galopp davon'],'Landmaschinen sind laut und groß, Pferde erschrecken leicht. Anhalten und ein Zeichen geben ist am sichersten.'),
('Straßenverkehr','Wo reitest du auf der Straße?','Am rechten Fahrbahnrand, in Fahrtrichtung',['In der Mitte der Fahrbahn','Links, dem Verkehr entgegen'],'Der rechte Rand ist für Reiter vorgesehen, und so rechnen Autofahrer mit dir.'),
('Straßenverkehr','Du hast ein junges, unerfahrenes Pferd. Wie gehst du auf die Straße?','Nur mit einem erfahrenen Begleitpferd und nach Absprache mit dem Reitlehrer',['Allein, so lernt es am schnellsten','Im Trab, damit es keine Zeit zum Erschrecken hat'],'Ein ruhiges Pferd gibt Sicherheit. Junge Pferde müssen Verkehr schrittweise kennenlernen.'),
('Straßenverkehr','Ein Auto hat langsam für euch gewartet und fährt vorbei. Was tust du?','Ich danke freundlich, zum Beispiel mit einem Nicken oder Handzeichen',['Nichts, das ist selbstverständlich','Ich trabe schnell an'],'Ein Dank macht Autofahrer freundlicher zu allen Reitern, und sie fahren beim nächsten Mal wieder langsam.'),
]
def js(t): return t.replace("\\","\\\\").replace("'","\\'")
if "Du willst ein Pferd aus der Box holen" not in s:
    lines=''.join(" {c:'%s',q:'%s',a:'%s',w:[%s],x:'%s'},\n"%(js(c),js(q),js(a),','.join("'"+js(w)+"'" for w in ws),js(x)) for c,q,a,ws,x in NEW)
    i=s.index("const S=[");j=s.index("\n];",i)
    head=s[:j]
    if head.rstrip().endswith('}'): head=head.rstrip()+','
    s=head+'\n'+lines.rstrip('\n')+s[j:]
if 'id="thQnum"' not in s:
    s=s.replace('<span>Punkte <strong id="thQsc">0</strong> / <span id="thQmx">0</span></span></div>','<span>Frage <strong id="thQnum">1</strong> / <span id="thQtot">1</span> · Punkte <strong id="thQsc">0</strong> / <span id="thQmx">0</span></span></div>',1)
    s=s.replace(" qcur=QS[qbag.pop()];qdone=false;"," const qn=pool().length;qcur=QS[qbag.pop()];qdone=false;g('thQnum').textContent=qn-qbag.length;g('thQtot').textContent=qn;",1)
s=re.sub(r'(<meta name="app-version" content=")[^"]*',r'\g<1>2026-11-01zzo',s,count=1)
open('index.html','w',encoding='utf8').write(s)
